import React, { useState, useRef, useEffect, useMemo } from "react"
import type {
  ChatMessage,
  ProjectVersion,
  GenerationProvenance,
} from "../lib/store"
import { useApp } from "../store/AppContext"
import ConfirmationModal from "./ConfirmationModal"
import type { ActivityStatus } from "../lib/activityStatus"
import { statusToLine } from "../lib/activityStatus"
import StructuredEventCards from "./StructuredEventCards"
import StartupMentor from "./StartupMentor"

interface Props {
  messages: ChatMessage[]
  versions: ProjectVersion[]
  isGenerating: boolean
  activityStatus?: ActivityStatus
  activeTab: "workspace" | "history" | "timeline" | "chat"
  setActiveTab: (t: "workspace" | "history") => void
  projectName?: string
  failedPrompt?: string | null
  onRetry?: () => void
  onRestore?: (versionId: string) => void
  onFork?: (versionId: string) => void
  lastGeneration?: GenerationProvenance
  onRevertOperation?: (path: string) => void
  onSelectFile?: (filePath: string) => void
}

/**
 * Minimalist, production-grade Conversation Timeline (Lovable / Bolt / Replit inspired)
 */
export default function ConversationPanel({
  messages,
  versions,
  isGenerating,
  activityStatus,
  activeTab,
  setActiveTab,
  projectName = "Untitled App",
  failedPrompt,
  onRetry,
  onRestore,
  onFork,
  lastGeneration,
  onRevertOperation,
  onSelectFile,
}: Props) {
  const { addToast } = useApp()
  const { state } = useApp()
  const bottomRef = useRef<HTMLDivElement>(null)
  const [restoreModalVersion, setRestoreModalVersion] = useState<string | null>(null)
  const [copiedId, setCopiedId] = useState<string | null>(null)

  const isWorkspaceTab =
    activeTab === "workspace" ||
    activeTab === "timeline" ||
    activeTab === "chat"

  // Auto-scroll to bottom on new messages or generation updates
  useEffect(() => {
    if (isWorkspaceTab) {
      bottomRef.current?.scrollIntoView({ behavior: "smooth" })
    }
  }, [messages, isWorkspaceTab, isGenerating])

  const copyToClipboard = (text: string, id: string) => {
    navigator.clipboard.writeText(text)
    setCopiedId(id)
    addToast("Copied to clipboard", "default")
    setTimeout(() => setCopiedId(null), 2000)
  }

  const statusInfo = useMemo(() => {
    if (!activityStatus) return null
    return statusToLine(activityStatus)
  }, [activityStatus])

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        height: "100%",
        background: "#0c0c0e",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* ── Top Tab Strip ── */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "0 12px",
          height: 40,
          background: "rgba(255, 255, 255, 0.015)",
          borderBottom: "1px solid rgba(255, 255, 255, 0.04)",
          flexShrink: 0,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
          <button
            type="button"
            onClick={() => setActiveTab("workspace")}
            style={{
              padding: "4px 10px",
              borderRadius: 6,
              fontSize: 12,
              fontWeight: 500,
              fontFamily: "var(--font-geist)",
              cursor: "pointer",
              border: "none",
              background: isWorkspaceTab
                ? "rgba(255, 255, 255, 0.08)"
                : "transparent",
              color: isWorkspaceTab
                ? "#ffffff"
                : "rgba(255, 255, 255, 0.45)",
              transition: "all 0.15s ease",
            }}
          >
            Workspace
          </button>

          <button
            type="button"
            onClick={() => setActiveTab("history")}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              padding: "4px 10px",
              borderRadius: 6,
              fontSize: 12,
              fontWeight: 500,
              fontFamily: "var(--font-geist)",
              cursor: "pointer",
              border: "none",
              background: activeTab === "history"
                ? "rgba(255, 255, 255, 0.08)"
                : "transparent",
              color: activeTab === "history"
                ? "#ffffff"
                : "rgba(255, 255, 255, 0.45)",
              transition: "all 0.15s ease",
            }}
          >
            <span>History</span>
            {versions.length > 0 && (
              <span
                style={{
                  fontSize: 10,
                  padding: "0 5px",
                  borderRadius: 10,
                  background: "rgba(255, 255, 255, 0.1)",
                  color: "rgba(255, 255, 255, 0.7)",
                  fontFamily: "var(--font-mono-jetbrains)",
                }}
              >
                {versions.length}
              </span>
            )}
          </button>
        </div>

        {/* Live generation pulse pill */}
        {isGenerating && (
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              padding: "2px 8px",
              borderRadius: 12,
              background: "rgba(96, 165, 250, 0.12)",
              border: "1px solid rgba(96, 165, 250, 0.25)",
            }}
          >
            <span
              style={{
                width: 6,
                height: 6,
                borderRadius: "50%",
                background: "#60a5fa",
                boxShadow: "0 0 8px #60a5fa",
                animation: "pulse 1.5s infinite",
              }}
            />
            <span
              style={{
                fontSize: 10.5,
                fontWeight: 500,
                color: "#93c5fd",
                fontFamily: "var(--font-geist)",
              }}
            >
              {statusInfo?.title || "Building..."}
            </span>
          </div>
        )}
      </div>

      {/* ── Main View Content ── */}
      {isWorkspaceTab ? (
        <div
          style={{
            flex: 1,
            overflowY: "auto",
            padding: "16px 14px 24px",
            display: "flex",
            flexDirection: "column",
            gap: 16,
          }}
        >
          {/* Startup Mentor Chip if active */}
          <StartupMentor projectName={projectName} />

          {/* Empty State */}
          {messages.length === 0 && (
            <div
              style={{
                margin: "auto 0",
                padding: "32px 16px",
                textAlign: "center",
                color: "rgba(255, 255, 255, 0.4)",
              }}
            >
              <div
                style={{
                  width: 36,
                  height: 36,
                  borderRadius: 10,
                  background: "rgba(255, 255, 255, 0.04)",
                  border: "1px solid rgba(255, 255, 255, 0.08)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  margin: "0 auto 12px",
                  color: "#60a5fa",
                  fontSize: 16,
                }}
              >
                ✦
              </div>
              <div
                style={{
                  fontSize: 13,
                  fontWeight: 500,
                  color: "rgba(255, 255, 255, 0.8)",
                  marginBottom: 4,
                }}
              >
                What would you like to build?
              </div>
              <div style={{ fontSize: 11.5, color: "rgba(255, 255, 255, 0.4)", maxWidth: 280, margin: "0 auto" }}>
                Type an instruction below to start generating components, APIs, or full features.
              </div>
            </div>
          )}

          {/* Messages Stream */}
          {messages.map((msg, idx) => {
            const isUser = msg.role === "user"

            if (isUser) {
              return (
                <div
                  key={msg.id || `msg-${idx}`}
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "flex-end",
                    gap: 4,
                    alignSelf: "flex-end",
                    maxWidth: "92%",
                  }}
                >
                  <div
                    style={{
                      padding: "10px 14px",
                      borderRadius: "14px 14px 3px 14px",
                      background: "rgba(255, 255, 255, 0.06)",
                      border: "1px solid rgba(255, 255, 255, 0.1)",
                      color: "rgba(255, 255, 255, 0.95)",
                      fontSize: 13,
                      lineHeight: 1.55,
                      fontFamily: "var(--font-geist)",
                      wordBreak: "break-word",
                      whiteSpace: "pre-wrap",
                    }}
                  >
                    {msg.content}
                  </div>
                  {msg.timestamp && (
                    <span
                      style={{
                        fontSize: 10,
                        color: "rgba(255, 255, 255, 0.3)",
                        paddingRight: 4,
                        fontFamily: "var(--font-mono-jetbrains)",
                      }}
                    >
                      {msg.timestamp}
                    </span>
                  )}
                </div>
              )
            }

            // Assistant Message
            return (
              <div
                key={msg.id || `msg-${idx}`}
                className="group"
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: 8,
                  padding: "12px 14px",
                  borderRadius: 12,
                  background: "rgba(255, 255, 255, 0.02)",
                  border: "1px solid rgba(255, 255, 255, 0.05)",
                  position: "relative",
                  transition: "border-color 0.15s ease",
                }}
              >
                {/* Assistant Header */}
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                    <span style={{ color: "#60a5fa", fontSize: 12 }}>✦</span>
                    <span
                      style={{
                        fontSize: 12,
                        fontWeight: 600,
                        color: "rgba(255, 255, 255, 0.9)",
                        fontFamily: "var(--font-geist)",
                      }}
                    >
                      Shango
                    </span>
                    <span
                      style={{
                        fontSize: 10,
                        color: "rgba(255, 255, 255, 0.35)",
                        fontFamily: "var(--font-mono-jetbrains)",
                      }}
                    >
                      {msg.pending ? "generating..." : "completed"}
                    </span>
                  </div>

                  {/* Micro Actions (Copy, Checkpoint) */}
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 4,
                      opacity: 0.6,
                    }}
                  >
                    <button
                      type="button"
                      onClick={() => copyToClipboard(msg.content, msg.id)}
                      title="Copy response"
                      style={{
                        background: "transparent",
                        border: "none",
                        cursor: "pointer",
                        padding: "2px 5px",
                        borderRadius: 4,
                        color: "rgba(255, 255, 255, 0.5)",
                        fontSize: 11,
                      }}
                    >
                      {copiedId === msg.id ? "✓ Copied" : "Copy"}
                    </button>
                  </div>
                </div>

                {/* Structured event cards & prose */}
                <StructuredEventCards
                  content={msg.content}
                  onSelectFile={onSelectFile}
                />

                {/* Loading indicator when pending */}
                {msg.pending && (
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 6,
                      fontSize: 11.5,
                      color: "#60a5fa",
                      fontFamily: "var(--font-geist)",
                      marginTop: 4,
                    }}
                  >
                    <span
                      style={{
                        width: 5,
                        height: 5,
                        borderRadius: "50%",
                        background: "#60a5fa",
                        animation: "pulse 1s infinite",
                      }}
                    />
                    <span>{statusInfo?.title || "Composing response..."}</span>
                  </div>
                )}
              </div>
            )
          })}

          {/* Failed Prompt / Retry Banner */}
          {failedPrompt && (
            <div
              style={{
                padding: "10px 14px",
                borderRadius: 8,
                background: "rgba(239, 68, 68, 0.08)",
                border: "1px solid rgba(239, 68, 68, 0.2)",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                gap: 10,
              }}
            >
              <div style={{ fontSize: 12, color: "#fca5a5", fontFamily: "var(--font-geist)" }}>
                Generation was interrupted.
              </div>
              {onRetry && (
                <button
                  type="button"
                  onClick={onRetry}
                  style={{
                    padding: "4px 10px",
                    borderRadius: 6,
                    background: "rgba(239, 68, 68, 0.2)",
                    border: "1px solid rgba(239, 68, 68, 0.3)",
                    color: "#ffffff",
                    fontSize: 11,
                    fontWeight: 500,
                    cursor: "pointer",
                  }}
                >
                  Retry
                </button>
              )}
            </div>
          )}

          <div ref={bottomRef} style={{ height: 1 }} />
        </div>
      ) : (
        /* ── History Tab ── */
        <div
          style={{
            flex: 1,
            overflowY: "auto",
            padding: "16px 14px",
            display: "flex",
            flexDirection: "column",
            gap: 10,
          }}
        >
          {versions.length === 0 ? (
            <div
              style={{
                margin: "auto 0",
                textAlign: "center",
                color: "rgba(255, 255, 255, 0.4)",
                fontSize: 12,
                fontFamily: "var(--font-geist)",
              }}
            >
              No checkpoints created yet.
            </div>
          ) : (
            versions.map((ver, idx) => (
              <div
                key={ver.id || `ver-${idx}`}
                style={{
                  padding: "10px 12px",
                  borderRadius: 8,
                  background: "rgba(255, 255, 255, 0.02)",
                  border: "1px solid rgba(255, 255, 255, 0.06)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  fontFamily: "var(--font-geist)",
                }}
              >
                <div style={{ display: "flex", flexDirection: "column", gap: 3, minWidth: 0 }}>
                  <div
                    style={{
                      fontSize: 12,
                      fontWeight: 500,
                      color: "rgba(255, 255, 255, 0.88)",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {ver.label || `Checkpoint ${versions.length - idx}`}
                  </div>
                  <div
                    style={{
                      fontSize: 10,
                      color: "rgba(255, 255, 255, 0.4)",
                      fontFamily: "var(--font-mono-jetbrains)",
                    }}
                  >
                    {ver.timestamp || "Recent"} · {ver.files?.length || 0} files
                  </div>
                </div>

                <div style={{ display: "flex", alignItems: "center", gap: 6, flexShrink: 0 }}>
                  {onRestore && (
                    <button
                      type="button"
                      onClick={() => setRestoreModalVersion(ver.id)}
                      style={{
                        padding: "3px 8px",
                        borderRadius: 5,
                        background: "rgba(255, 255, 255, 0.06)",
                        border: "1px solid rgba(255, 255, 255, 0.1)",
                        color: "rgba(255, 255, 255, 0.85)",
                        fontSize: 11,
                        cursor: "pointer",
                        fontFamily: "var(--font-geist)",
                      }}
                    >
                      Restore
                    </button>
                  )}
                  {onFork && (
                    <button
                      type="button"
                      onClick={() => onFork(ver.id)}
                      style={{
                        padding: "3px 8px",
                        borderRadius: 5,
                        background: "transparent",
                        border: "1px solid rgba(255, 255, 255, 0.08)",
                        color: "rgba(255, 255, 255, 0.6)",
                        fontSize: 11,
                        cursor: "pointer",
                        fontFamily: "var(--font-geist)",
                      }}
                    >
                      Fork
                    </button>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {/* Confirmation Modal for Restore */}
      {restoreModalVersion && (
        <ConfirmationModal
          open={!!restoreModalVersion}
          title="Restore Checkpoint"
          message="Restoring this checkpoint will roll back the workspace files to this point. Any uncommitted edits will be replaced."
          confirmLabel="Restore Checkpoint"
          onConfirm={() => {
            if (restoreModalVersion && onRestore) {
              onRestore(restoreModalVersion)
            }
            setRestoreModalVersion(null)
          }}
          onCancel={() => setRestoreModalVersion(null)}
        />
      )}
    </div>
  )
}

import {
  createContext,
  useContext,
  useReducer,
  useCallback,
  useRef,
  useEffect,
  useState,
  type ReactNode,
} from "react"
import {
  type Project,
  type ChatMessage,
  type Version,
  type ProjectTemplateOrigin,
  generateId,
} from "../lib/store"
import {
  DEFAULT_INSTALLED_SKILL_IDS,
  DEFAULT_ENABLED_SKILL_IDS,
} from "../lib/skills"
import { DEFAULT_CONNECTED_CONNECTOR_IDS } from "../lib/connectors"
import {
  DEFAULT_DEPLOYMENT_RECORDS,
  normalizeDeploymentRecords,
  type DeploymentRecord,
} from "../lib/deployments"
import {
  loadPersistedProjectState,
  saveProjectStateSnapshot,
  loadPersistedUser,
  savePersistedUser,
  normalizeProject,
  normalizeProjects,
  mergePersistedProjects,
} from "../lib/persistence"
import {
  generateProjectResponse,
  type GenerationResult,
} from "../lib/generation"
import {
  deriveProjectArtifact,
  mergeWorkspaceFilesWithArtifact,
  updateProjectFile,
} from "../lib/workspace"
import {
  readUsagePeriod,
  recordGeneration,
  type UsagePeriod,
} from "../lib/usageMeter"

// ─── Types ────────────────────────────────────────────────────────────────────

export type { Project, ChatMessage, Version }

export interface Toast {
  id: string
  message: string
  type: "default" | "success" | "error"
  action?: { label: string onClick: () => void }
}

export interface Notification {
  id: string
  message: string
  read: boolean
  timestamp: string
  link?: string
}

export interface User {
  name: string
  email: string
  avatar?: string
  plan: "free" | "pro"
}

export type ModalType = "share" | "deploy" | "export" | "auth" | "confirm" | "settings" | "project-settings" | null

export interface ConfirmPayload {
  title: string
  description: string
  confirmLabel?: string
  onConfirm: () => void
}

export interface CreateProjectOptions {
  model?: string
  mode?: "plan" | "build"
  name?: string
  description?: string
  template?: ProjectTemplateOrigin
}

interface AppState {
  user: User | null
  projects: Project[]
  activeProjectId: string | null
  persistenceError: string | null
  modal: ModalType
  confirmPayload: ConfirmPayload | null
  toasts: Toast[]
  isCommandPaletteOpen: boolean
  isShortcutsOpen: boolean
  isProfileOpen: boolean
  isNotificationsOpen: boolean
  notifications: Notification[]
  isForge: boolean
  installedSkills: string[] // skill IDs
  enabledSkills: string[] // subset of installed that are active
  connectedConnectors: string[] // connector IDs
  deploymentRecords: DeploymentRecord[]
}

type Action = { type: "SET_USER" payload: User | null } | {
  type: "ADD_PROJECT"
  payload: Project
} | { type: "SET_PROJECTS" payload: Project[] } | {
  type: "UPDATE_PROJECT"
  payload: Partial<Project> & { id: string }
} | { type: "DELETE_PROJECT" payload: string } | {
  type: "STAR_PROJECT"
  payload: string
} | { type: "SET_ACTIVE_PROJECT" payload: string | null } | {
  type: "OPEN_MODAL"
  payload: ModalType
} | { type: "CLOSE_MODAL" } | {
  type: "SET_CONFIRM"
  payload: ConfirmPayload | null
} | { type: "PUSH_TOAST" payload: Toast } | {
  type: "REMOVE_TOAST"
  payload: string
} | { type: "TOGGLE_COMMAND_PALETTE" } | { type: "TOGGLE_SHORTCUTS" } | {
  type: "TOGGLE_PROFILE"
} | { type: "TOGGLE_NOTIFICATIONS" } | {
  type: "ADD_NOTIFICATION"
  payload: Notification
} | { type: "MARK_ALL_READ" } | { type: "START_FORGE" } | {
  type: "END_FORGE"
} | { type: "INSTALL_SKILL" payload: string } | {
  type: "UNINSTALL_SKILL"
  payload: string
} | { type: "ENABLE_SKILL" payload: string } | {
  type: "DISABLE_SKILL"
  payload: string
} | { type: "CONNECT_CONNECTOR" payload: string } | {
  type: "DISCONNECT_CONNECTOR"
  payload: string
} | { type: "ADD_DEPLOYMENT" payload: DeploymentRecord } | {
  type: "UPDATE_DEPLOYMENT"
  payload: Partial<DeploymentRecord> & { id: string }
} | { type: "SET_DEPLOYMENT_RECORDS" payload: DeploymentRecord[] }

const INITIAL_NOTIFICATIONS: Notification[] = []

const INITIAL: AppState = {
  user: null,
  projects: [],
  activeProjectId: null,
  persistenceError: null,
  modal: null,
  confirmPayload: null,
  toasts: [],
  isCommandPaletteOpen: false,
  isShortcutsOpen: false,
  isProfileOpen: false,
  isNotificationsOpen: false,
  notifications: INITIAL_NOTIFICATIONS,
  isForge: false,
  installedSkills: DEFAULT_INSTALLED_SKILL_IDS,
  enabledSkills: DEFAULT_ENABLED_SKILL_IDS,
  connectedConnectors: DEFAULT_CONNECTED_CONNECTOR_IDS,
  deploymentRecords: DEFAULT_DEPLOYMENT_RECORDS,
}

function hydrateInitialState(): AppState {
  const persisted = loadPersistedProjectState()
  const persistedUser = loadPersistedUser()
  // Sanitize persisted projects to remove large HTML/code blobs accidentally
  // stored in message content (one-time defensive hygiene).
  function sanitizePersistedProjects(projects: any[]) {
    if (!Array.isArray(projects)) return projects
    return projects.map((proj) => {
      if (!proj || !Array.isArray(proj.messages)) return proj
      const cleaned = proj.messages.map((m: any) => {
        try {
          const content =
            typeof m.content === "string" ? m.content : String(m.content ?? "")
          const hasHtml = /<[^>]+>/.test(content)
          const overlyLong = content.length > 1200
          const looksLikeCode =
            /function\s*\(|const\s+[a-zA-Z_$]|import\s+\w+|console\.log\(|<script\b/i.test(
              content,
            )
          if (hasHtml || overlyLong || looksLikeCode) {
            return {
              ...m,
              content: "[suppressed preview content]",
              timestamp: m.timestamp ?? new Date().toISOString(),
            }
          }
        } catch {
          // noop
        }
        return m
      })
      return { ...proj, messages: cleaned }
    })
  }
  if (persisted.state && Array.isArray(persisted.state.projects)) {
    const sanitized = sanitizePersistedProjects(persisted.state.projects)
    return {
      ...INITIAL,
      user: persistedUser,
      projects: normalizeProjects(sanitized as any[]),
      activeProjectId: persisted.state.activeProjectId,
      persistenceError: persisted.error ?? null,
    }
  }
  return {
    ...INITIAL,
    user: persistedUser,
    persistenceError: persisted.error ?? null,
  }
}

function reducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case "SET_USER":
      return { ...state, user: action.payload }
    case "ADD_PROJECT":
      return { ...state, projects: [action.payload, ...state.projects] }
    case "SET_PROJECTS":
      return { ...state, projects: action.payload }
    case "UPDATE_PROJECT":
      return {
        ...state,
        projects: state.projects.map((p) =>
          p.id === action.payload.id
            ? normalizeProject({
                ...p,
                ...action.payload,
                lastEdited: new Date().toISOString(),
                updatedAt: new Date().toISOString(),
              })
            : normalizeProject(p),
        ),
      }
    case "DELETE_PROJECT":
      return {
        ...state,
        projects: state.projects.filter((p) => p.id !== action.payload),
        activeProjectId:
          state.activeProjectId === action.payload
            ? null
            : state.activeProjectId,
      }
    case "STAR_PROJECT":
      return {
        ...state,
        projects: state.projects.map((p) =>
          p.id === action.payload ? { ...p, starred: !p.starred } : p,
        ),
      }
    case "SET_ACTIVE_PROJECT":
      return { ...state, activeProjectId: action.payload }
    case "OPEN_MODAL":
      return { ...state, modal: action.payload }
    case "CLOSE_MODAL":
      return { ...state, modal: null, confirmPayload: null }
    case "SET_CONFIRM":
      return { ...state, confirmPayload: action.payload }
    case "PUSH_TOAST":
      return { ...state, toasts: [...state.toasts.slice(-2), action.payload] }
    case "REMOVE_TOAST":
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.payload),
      }
    case "TOGGLE_COMMAND_PALETTE":
      return { ...state, isCommandPaletteOpen: !state.isCommandPaletteOpen }
    case "TOGGLE_SHORTCUTS":
      return { ...state, isShortcutsOpen: !state.isShortcutsOpen }
    case "TOGGLE_PROFILE":
      return { ...state, isProfileOpen: !state.isProfileOpen }
    case "TOGGLE_NOTIFICATIONS":
      return { ...state, isNotificationsOpen: !state.isNotificationsOpen }
    case "ADD_NOTIFICATION":
      return {
        ...state,
        notifications: [action.payload, ...state.notifications],
      }
    case "MARK_ALL_READ":
      return {
        ...state,
        notifications: state.notifications.map((n) => ({ ...n, read: true })),
      }
    case "START_FORGE":
      return { ...state, isForge: true }
    case "END_FORGE":
      return { ...state, isForge: false }
    case "INSTALL_SKILL":
      if (state.installedSkills.includes(action.payload)) return state
      return {
        ...state,
        installedSkills: [...state.installedSkills, action.payload],
        enabledSkills: [...state.enabledSkills, action.payload],
      }
    case "UNINSTALL_SKILL":
      return {
        ...state,
        installedSkills: state.installedSkills.filter(
          (id) => id !== action.payload,
        ),
        enabledSkills: state.enabledSkills.filter(
          (id) => id !== action.payload,
        ),
      }
    case "ENABLE_SKILL":
      if (state.enabledSkills.includes(action.payload)) return state
      return {
        ...state,
        enabledSkills: [...state.enabledSkills, action.payload],
      }
    case "DISABLE_SKILL":
      return {
        ...state,
        enabledSkills: state.enabledSkills.filter(
          (id) => id !== action.payload,
        ),
      }
    case "CONNECT_CONNECTOR":
      if (state.connectedConnectors.includes(action.payload)) return state
      return {
        ...state,
        connectedConnectors: [...state.connectedConnectors, action.payload],
      }
    case "DISCONNECT_CONNECTOR":
      return {
        ...state,
        connectedConnectors: state.connectedConnectors.filter(
          (id) => id !== action.payload,
        ),
      }
    case "ADD_DEPLOYMENT":
      return {
        ...state,
        deploymentRecords: [action.payload, ...state.deploymentRecords],
      }
    case "UPDATE_DEPLOYMENT":
      return {
        ...state,
        deploymentRecords: state.deploymentRecords.map((d) =>
          d.id === action.payload.id ? { ...d, ...action.payload } : d,
        ),
      }
    case "SET_DEPLOYMENT_RECORDS":
      return { ...state, deploymentRecords: action.payload }
    default:
      return state
  }
}

